using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class SpecialV66Tests {
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: v66 "+name);Console.WriteLine("PASS: v66 "+name);}
 public static Simulation Load(string root,bool foreign=false){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(w);if(foreign){var seed=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(w.Units.First(a=>a.Type==0&&a.Owner==0&&VisualCatalog.Visible(a))))!;seed.Slot=w.Units.Max(a=>a.Slot)+1;seed.Owner=1;seed.X+=4096;w.Units.Add(seed);var home=w.Buildings.First(b=>b.Owner==0&&b.Type==2);int cell=home.Cell+10+256*5;var b=new Building(700,16,1,cell);w.Buildings.Add(b);var resident=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(w.Units.First(a=>a.Type==9&&a.Owner==0)))!;resident.Slot=w.Units.Max(a=>a.Slot)+1;resident.Owner=1;resident.LegacyState=14;w.Units.Add(resident);w.BuildingResidents[b.Slot]=new(){resident.Slot};w.Resources[1]=w.Resources[5]=w.Resources[9]=300;w.Buildings.Add(new Building(701,8,0,home.Cell+20+256*10));w.Buildings.Add(new Building(702,8,1,home.Cell+25+256*10));}
  var s=new Simulation(w,new(){StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==3).Levels.ToArray(),SelectedBranch=0});for(int n=0;n<24;n++)foreach(int kind in new[]{0,1,2})s.GrantTestResource(kind);for(int branch=0;branch<4;branch++)while(s.GrantTestTechnology(branch)){}return s;}
 public static Actor Recruit(Simulation s,int type){var b=Simulation.ProductionData.Buildings.First(b=>b.Troops.Contains(type));int slot=type is 5 or 6 or 7?s.World.Buildings.First(b=>b.Type==2&&b.Owner==0).Slot:ProductionV65Tests.Staff(s,b.Building);if(!s.Recruit(type,slot))throw new Exception("Recruit fixture "+type);var job=s.Recruitments.Last();for(int i=0;i<12000&&!job.Finished;i++)s.Step();if(!job.Finished)throw new Exception("Recruit fixture timed out");return s.World.Units.First(a=>a.Slot==job.SettlerSlot);}
 public static int Teach(Simulation s){int lib=ProductionV65Tests.Staff(s,6);foreach(int id in Enumerable.Range(0,5)){Check(s.CanLearnSpell(id,lib)&&s.LearnSpell(id,lib),"library learns original spell "+id);for(int i=0;i<10000&&!s.SpellLearned(id);i++)s.Step();Check(s.SpellLearned(id),"learning completes "+id);}return lib;}
 static void Roundtrip(Simulation s,string root,bool foreign,string name){var copy=Load(root,foreign);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),name);}
 public static void Run(string root){
  Check(Simulation.SpecialData.Aerial.SequenceEqual(new[]{16,17}),"native aircraft classification");Check(Simulation.SpecialData.ResourceValues.SequenceEqual(new[]{2,1,1}),"native market resource values");
  var s=Load(root,true);int lib=ProductionV65Tests.Staff(s,6);int food=s.World.Resources[0],rock=s.World.Resources[4];Check(s.LearnSpell(0,lib)&&s.World.Resources[0]==food-6&&s.World.Resources[4]==rock-4,"learning charges original costs once");string pending=s.Serialize();Check(!s.LearnSpell(1,lib)&&s.Serialize()==pending,"busy library rejects duplicate without cost");Roundtrip(s,root,true,"pending spell survives save load");for(int i=0;i<5000&&!s.SpellLearned(0);i++)s.Step();
  foreach(int id in new[]{1,2,3,4}){Check(s.LearnSpell(id,lib),"learn subsequent spell "+id);for(int i=0;i<10000&&!s.SpellLearned(id);i++)s.Step();Check(s.SpellLearned(id),"subsequent learning completes "+id);}
  var druid=Recruit(s,4);int crystal=ResearchTests.Build(s,17,false);var c=s.World.Buildings.First(b=>b.Slot==crystal);druid.X=(c.Cell&255)*1024;druid.Y=((c.Cell>>8)+1)*1024;int initialMana=druid.Mana;for(int i=0;i<60;i++)s.Step();Check(druid.Mana==initialMana+60/s.ManaPeriod(druid),"crystal restores mana with native research modifier");druid.X=0;druid.Y=0;initialMana=druid.Mana;for(int i=0;i<60;i++)s.Step();Check(druid.Mana==initialMana,"no free mana away from crystal");
  var ally=s.World.Units.First(a=>a.Type==0&&a.Owner==0&&VisualCatalog.Visible(a));var enemy=s.World.Units.First(a=>a.Type==0&&a.Owner==1);enemy.Health=100;enemy.LegacyState=7;druid.X=ally.X;druid.Y=ally.Y+1024;enemy.X=ally.X+1024;enemy.Y=ally.Y;druid.Mana=s.ManaMaximum(druid);s.UpdateVisibility();int enemyCell=enemy.Y/1024*256+enemy.X/1024;
  string before=s.Serialize();Check(!s.CastSpell(druid,1,ally.Y/1024*256+ally.X/1024,ally)&&s.Serialize()==before,"petrification rejects allied target atomically");int mana=druid.Mana;Check(s.CastSpell(druid,1,enemyCell,enemy)&&druid.Mana==mana-2,"petrification costs two mana");Check(enemy.PetrifiedUntil==s.Tick+400,"native petrification duration");s.Order(enemy,enemy.X/1024+1,enemy.Y/1024);int ex=enemy.X,ey=enemy.Y;for(int i=0;i<40;i++)s.Step();Check(enemy.X==ex&&enemy.Y==ey,"petrified actor cannot move");Roundtrip(s,root,true,"active petrification and mana survive save load");
  int allyCell=ally.Y/1024*256+ally.X/1024;Check(s.CastSpell(druid,3,allyCell,ally)&&ally.ArmoredUntil==s.Tick+400,"armour applies original timed protection");Check(s.CastSpell(druid,2,allyCell,ally),"mirror creates playable duplicate");var mirror=s.World.Units.Single(a=>a.Slot>=40000);Check(mirror.Type==ally.Type&&mirror.Owner==ally.Owner&&mirror.Food==0&&mirror.Rock==0,"mirror preserves class without duplicating cargo");int hp=mirror.Health;for(int i=0;i<20;i++)s.Step();Check(mirror.Health==hp-1,"mirror loses one health each twenty updates");Check(!s.CanEnterBuilding(mirror,s.World.Buildings.First(b=>b.Type==2&&b.Owner==0).Slot),"illusion cannot create a permanent colonist");Roundtrip(s,root,true,"mirror survives save and original actor validation");
  int visionCell=Enumerable.Range(0,65536).First(cell=>(cell&255)<s.World.Width&&(cell>>8)<s.World.Height&&s.InSight(cell)&&Math.Abs((cell&255)-druid.X/1024)<15);druid.Mana=s.ManaMaximum(druid);Check(s.CastSpell(druid,0,visionCell),"vision casts on terrain");Check(s.InSight(visionCell)&&s.Special.Zones.Any(z=>z.Spell==0),"vision contributes to fog of war");druid.Mana=0;before=s.Serialize();Check(!s.CastSpell(druid,0,visionCell)&&s.Serialize()==before,"insufficient mana does not alter orders");druid.Mana=s.ManaMaximum(druid);enemy.Health=100;enemy.PetrifiedUntil=0;ex=enemy.X;ey=enemy.Y;Check(s.CastSpell(druid,4,enemy.Y/1024*256+enemy.X/1024)&&enemy.Health==10,"nova applies native ninety damage on impact area");Roundtrip(s,root,true,"all spell states and paid learning persist");
  var air=Load(root);var heliped=Recruit(air,16);int water=Enumerable.Range(0,65536).First(cell=>(cell&255)<air.World.Width&&(cell>>8)<air.World.Height&&!air.Passable(cell&255,cell>>8)&&air.World.Tiles[cell] is >=0x1dd and <0x261);Check(air.Order(heliped,water&255,water>>8),"aircraft accepts water destination");Roundtrip(air,root,false,"aerial route survives save load");for(int i=0;i<10000&&heliped.Route.Count>0;i++)air.Step();Check(heliped.Route.Count==0&&heliped.X/1024==(water&255)&&heliped.Y/1024==(water>>8),"aircraft crosses obstacles and reaches water");Check(!air.Order(air.World.Units.First(a=>a.Type==0&&a.Owner==0),water&255,water>>8),"ground troops still reject water");Check(!air.Order(heliped,-1,0)&&!air.Order(heliped,air.World.Width,air.World.Height),"aircraft stays inside map");
  foreach(int type in new[]{1,2,3,4,11,12,15,16,25}){var combat=Load(root,true);var a=Recruit(combat,type);var b=combat.World.Units.First(a=>a.Owner==1&&a.Type==0);b.X=a.X+1024;b.Y=a.Y;b.Health=100;Check(combat.Attack(a,b),"advanced troop can attack "+type);int ticks=combat.ReleaseTicks(a);for(int i=0;i<ticks;i++)combat.Step();Check(b.Health<100||combat.Arrows.Any(p=>p.SourceSlot==a.Slot),"native release produces damage/projectile "+type);Roundtrip(combat,root,true,"advanced combat persists "+type);}
  var trade=Load(root,true);int own=ProductionV65Tests.Staff(trade,16);var messenger=Recruit(trade,10);var other=trade.World.Buildings.First(b=>b.Type==16&&b.Owner==1);messenger.X=(other.Cell&255)*1024;messenger.Y=((other.Cell>>8)+3)*1024;trade.UpdateVisibility();Check(trade.ContactMarket(messenger,other.Slot),"messenger opens real market contact");for(int i=0;i<10000&&!trade.Special.Contacts.Any(c=>c.Arrived);i++)trade.Step();Check(trade.MarketPartners(own).Any(),"market contact completes after travel");
  int[] give={10,0,0},take={0,8,0};Check(trade.TradeScore(give,take)==100,"native neutral offer valuation");long[] totals=Enumerable.Range(0,3).Select(k=>Enumerable.Range(0,4).Sum(o=>(long)trade.World.Resources[k*4+o])).ToArray();int f=trade.World.Resources[0],r=trade.World.Resources[4];Check(trade.Trade(own,other.Slot,give,take)&&trade.World.Resources[0]==f-10&&trade.World.Resources[4]==r+8,"accepted trade transfers both stocks");Check(Enumerable.Range(0,3).All(k=>Enumerable.Range(0,4).Sum(o=>(long)trade.World.Resources[k*4+o])==totals[k]),"trade conserves all resources across players");before=trade.Serialize();Check(!trade.Trade(own,other.Slot,new[]{1,0,0},new[]{0,100,0})&&trade.Serialize()==before,"unfair proposal rejected without mutation");Roundtrip(trade,root,true,"completed trade and resource ledgers survive save load");
  var invalid=JsonNode.Parse(trade.Serialize())!;invalid["Special"]!["Trades"]![0]!["Received"]![1]=9;before=trade.Serialize();try{trade.Restore(invalid.ToJsonString());throw new Exception("Invalid trade accepted");}catch(InvalidDataException){}Check(trade.Serialize()==before,"corrupt trade rejected atomically");
  Console.WriteLine("ALL SPECIAL v66 TESTS PASSED");
 }
}
